mapper.sql:
WHERE m.deleted_at IS NULL
AND m.media_type = #{type}

  AND (LOWER(m.name) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(m.original_name) LIKE LOWER(CONCAT('%', #{keyword}, '%')))

mapper.select:
SELECT  FROM media m LEFT JOIN admin_users u ON u.id = m.uploaded_by

ORDER BY m.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT id, storage_key, deleted_at FROM media WHERE deleted_at IS NOT NULL AND id IN
#{id}
ORDER BY id FOR UPDATE
